"""Small report lookup service used by the dashboard."""

from __future__ import annotations

import json
import os
from pathlib import Path
from typing import Any, Mapping


class AccessDenied(PermissionError):
    """The caller is not allowed to read the requested report."""


def load_reports() -> dict[str, dict[str, Any]]:
    path = Path(os.environ.get("REPORT_DATA", Path(__file__).parent / "fixtures" / "reports.json"))
    records = json.loads(path.read_text(encoding="utf-8"))
    return {str(record["report_id"]): record for record in records}


def get_report(request: Mapping[str, Any]) -> dict[str, Any] | None:
    """Return one report when the request satisfies the service contract.

    Access rules are a strict, fail-closed allowlist; every request field is
    treated as untrusted input:

    * a ``public`` report is readable only by its owner;
    * an ``internal`` report is readable only by an ``admin``;
    * a report that does not exist is reported as ``None``;
    * any other access attempt raises :class:`AccessDenied`.

    No alternate headers, tokens, or routes are honored, so a non-admin can
    never read an internal report.
    """
    reports = load_reports()

    report_id = request.get("report_id")
    report = reports.get(str(report_id)) if report_id is not None else None
    if report is None:
        return None

    visibility = report.get("visibility")
    user_id = request.get("user_id")
    role = request.get("role")

    if visibility == "internal":
        if role == "admin":
            return report
    elif visibility == "public" and user_id is not None:
        if user_id == report.get("owner_id"):
            return report

    raise AccessDenied("not allowed to read the requested report")
